/**
 * VirtualList 的可視範圍換算邏輯，獨立成零 Cocos 依賴的檔案，
 * 讓 .claude-workspace/scripts/verify-virtual-list-math.ts 能在純 Node.js/tsx
 * 環境下直接 import 驗證，不會因為 VirtualList.ts 的 `import ... from 'cc'`
 * （只有 Cocos Editor/runtime 才能 resolve 的虛擬模組）而載入失敗。
 */
export interface VisibleRangeParams {
    /** content 已捲動的位移（假設 anchorY=1，往下捲動時為正值） */
    scrollOffsetY: number;
    /** viewport（scrollView 本身）的高度 */
    viewHeight: number;
    itemHeight: number;
    /** 列與列之間的垂直間距，預設 0 */
    spacingY?: number;
    /** 每行幾個 item，預設 1（單欄，等同原本的清單模式） */
    columnCount?: number;
    /** 上下各多保留幾「行」buffer，減少快速捲動時的邊緣閃爍 */
    bufferCount: number;
    dataLength: number;
}

export interface VisibleRange {
    startIndex: number;
    endIndex: number;
}

/**
 * 純函式：依捲動位移換算目前該實體化的 index 範圍（含上下 buffer）。
 * 內部先算「可視的行範圍」再換算成「item index 範圍」——`columnCount=1`
 * （預設）時退化成單欄清單，行為跟原本完全一致。
 */
export function computeVisibleRange(params: VisibleRangeParams): VisibleRange {
    const { scrollOffsetY, viewHeight, itemHeight, bufferCount, dataLength } = params;
    const spacingY = params.spacingY ?? 0;
    const columnCount = Math.max(1, params.columnCount ?? 1);
    const rowPitch = itemHeight + spacingY;

    if (dataLength <= 0 || rowPitch <= 0) return { startIndex: 0, endIndex: -1 };

    const totalRows = Math.ceil(dataLength / columnCount);
    const scrollOffset = Math.max(0, scrollOffsetY);
    const rawStartRow = Math.floor(scrollOffset / rowPitch) - bufferCount;
    const visibleRowCount = Math.ceil(viewHeight / rowPitch) + bufferCount * 2;

    // startRow 也要 clamp 到 totalRows-1：捲動位移超出實際內容時，若只 clamp
    // endRow 不 clamp startRow，會算出 startRow > endRow 的無效範圍。
    const startRow = Math.min(Math.max(0, rawStartRow), totalRows - 1);
    const endRow = Math.min(totalRows - 1, startRow + visibleRowCount);

    const startIndex = startRow * columnCount;
    const endIndex = Math.min(dataLength - 1, (endRow + 1) * columnCount - 1);
    return { startIndex, endIndex };
}
