import { _decorator, Node } from 'cc';
import { SymbolViewSpine } from './SymbolViewSpine';

const { ccclass, property } = _decorator;

/**
 * 消除爆破的顯示層：`symbol_frame` 炸開，靜態圖在動畫第 133ms 才消失。
 *
 * 那個 133ms 是美術表訂的規格，不是隨手抓的緩衝——爆破動畫前面幾格是「裂開」，符號必須還在，
 * 到碎片飛散那一格才該不見。原本寫在 `NgSymbol.playEliminate()` 裡，連同「播完要把靜態圖
 * `active` 還原，讓這個節點能被補牌重用」一起搬過來。
 *
 * 還原這件事現在更重要：改版後這顆物件是**池子裡的共用品**，歸還時沒還原的話，下一格租到它
 * 會直接是「沒有符號、只有爆破框」的狀態。所以還原放在 {@link onReturn}，不是放在播完的回呼裡
 * ——播到一半被打斷（例如整盤重置）時回呼不會來，但歸還一定會。
 */
@ccclass('1002/SymbolViewErase')
export class SymbolViewErase extends SymbolViewSpine {
    @property({
        type: Node,
        tooltip: '爆破途中要關掉的靜態圖節點。留空時整段演出就只有爆破框，符號會從頭到尾都在'
    })
    public staticImage: Node = null!;

    /** 靜態圖消失的時間點（秒，原速）。美術表規格 */
    private static readonly HIDE_AT_SEC = 0.133;

    /** 目前的播放倍率，決定靜態圖要在第幾秒關掉 */
    private timeScale: number = 1;

    public override setTimeScale(scale: number): void {
        super.setTimeScale(scale);
        this.timeScale = scale > 0 ? scale : 1;
    }

    /**
     * 播一次爆破，並排定靜態圖的消失時間。
     *
     * @param onComplete 播完時呼叫。
     */
    public override playOnce(onComplete: () => void): void {
        this.scheduleHide();
        super.playOnce(onComplete);
    }

    public override resetAni(): void {
        this.scheduleHide();
        super.resetAni();
    }

    /** 歸還：取消還沒觸發的排程並把靜態圖開回來，這顆物件才能被下一格乾淨地重用 */
    public override onReturn(): void {
        this.unscheduleAllCallbacks();
        if (this.staticImage?.isValid) this.staticImage.active = true;
        this.timeScale = 1;
        super.onReturn();
    }

    /** 排定「第 133ms 關掉靜態圖」；倍率越快，關得越早 */
    private scheduleHide(): void {
        if (!this.staticImage?.isValid) return;
        this.unscheduleAllCallbacks();
        this.staticImage.active = true;
        this.scheduleOnce(() => {
            if (this.staticImage?.isValid) this.staticImage.active = false;
        }, SymbolViewErase.HIDE_AT_SEC / this.timeScale);
    }
}
