import { _decorator, Node } from "cc";
import { EventComponent } from "../../events/EventComponent";
import { SlotMachineModel } from "../model/SlotMachineModel";
import { ReelView_1002 } from "./ReelView_1002";
import { ReelFlag } from "../symbol/SymbolState";
import type { AchieveItem } from "../../types/SpinTypes";

const { ccclass, property } = _decorator;

@ccclass("1002/SlotMachineView")
export class SlotMachineView extends EventComponent {
    @property([ReelView_1002])
    reelViews: ReelView_1002[] = [];

    public model: SlotMachineModel = null!;

    init(model: SlotMachineModel): void {
        this.model = model;

        for (let i = 0; i < this.reelViews.length; i++) {
            this.reelViews[i].init(model.reelModels[i]);
            this.reelViews[i].node.setSiblingIndex(i);
        }
    }

    applySpeed(bd: number, lt: number, ed: number): void {
        for (const reel of this.reelViews) {
            reel.applySpeed(bd, lt, ed);
        }
    }

    /** 目前的轉輪節奏設定，讀第一顆轉輪的值（applySpeed 一律整組套用，理論上彼此一致） */
    getSpeed(): { beginDuration: number; loopTime: number; endDuration: number } | null {
        return this.reelViews[0]?.getSpeed() ?? null;
    }

    applyEase(beginEase: string, endEase: string): void {
        for (const reel of this.reelViews) {
            reel.applyEase(beginEase, endEase);
        }
    }

    /** 目前的開始/結束緩動名稱，讀第一顆轉輪的值（applyEase 一律整組套用，理論上彼此一致） */
    getEase(): { beginEase: string; endEase: string } | null {
        return this.reelViews[0]?.getEase() ?? null;
    }

    getSymbolAt(col: number, row: number): Node | null {
        return this.reelViews[col]?.getVisibleSymbol(row) ?? null;
    }

    private static readonly SPINE_ANIM_MAP: Record<string, string> = {
        "fu":           "idle",
        "caishen":      "animation",
        "jin_chan":     "h2",
        "wealth_tree":  "h3",
        "golden_carp":  "h4",
        "golden_ruyi":  "h5",
        "a":            "n1",
        "k":            "n2",
        "q":            "n3",
        "j":            "n4",
        "ten":          "n5",
    };

    playSymbolWins(achieves: AchieveItem[], loop: boolean = true): Promise<void> {
        return new Promise<void>(resolve => {
            this.setSymbolSpinesTimeScale(1);
            const toPlay: { col: number; row: number; animName: string }[] = [];
            for (const achieve of achieves) {
                if (achieve.type !== "line" || !achieve.line || !achieve.icon) continue;
                const animName = SlotMachineView.SPINE_ANIM_MAP[achieve.icon];
                if (!animName) continue;
                const lineStr = String(achieve.line).replace(/,/g, '');
                const rows = lineStr.split('').map(Number);
                const len = achieve.length ?? rows.length;
                const isLeft = achieve.left === 1;
                for (let i = 0; i < len; i++) {
                    const col = isLeft ? i : (4 - i);
                    toPlay.push({ col, row: rows[i], animName });
                }
            }
            if (toPlay.length === 0) { resolve(); return; }

            // 壓黑非中獎圖示
            this.dimNonWinning(toPlay);

            if (loop) {
                // loop=true（輪播每條線）：等第一個 spine 播完一輪即繼續
                let resolved = false;
                const onFirst = () => { if (!resolved) { resolved = true; resolve(); } };
                let hasBound = false;
                for (const { col, row, animName } of toPlay) {
                    const cb = hasBound ? undefined : onFirst;
                    const played = this.reelViews[col]?.playWinAnim(row, animName, true, cb);
                    if (!hasBound && played) hasBound = true;
                }
                if (!hasBound) resolve();
            } else {
                // loop=false（全部一起播一次）：Cocos Creator setCompleteListener 對 loop=false 不觸發
                // 改用 timeout：動畫 1 秒 + 200ms buffer
                let hasAny = false;
                for (const { col, row, animName } of toPlay) {
                    const played = this.reelViews[col]?.playWinAnim(row, animName, false);
                    if (played) hasAny = true;
                }
                if (!hasAny) { resolve(); return; }
                this.scheduleOnce(resolve, 1);
            }
        });
    }

    stopAllSymbolWins(): void {
        for (const reel of this.reelViews) {
            reel.stopAllWinAnims();
        }
        this.setBlack(false);
    }

    /**
     * 整台調整符號動畫的播放速度。
     *
     * 改版前這裡是走 `reel.symbolSpines` 這個陣列——它從宣告到移除為止沒有任何地方 push 過，
     * 永遠是空的，所以這一支其實從來沒有生效過。現在委派給各欄逐格套用。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const reel of this.reelViews) {
            reel.setSymbolSpinesTimeScale(scale);
        }
    }

    /**
     * 開關整台的壓黑。
     *
     * 只打開輪軸旗標，不碰任何符號——沒有被指定中獎狀態的格子會自己透過
     * `SymbolCell.getTargetState()` 回退成 `SymbolState.Black`。這正是規格書 §11.7 描述的設計：
     * 中獎與壓黑由兩個互不知道對方的系統各自下指令，靠狀態機的優先權自然合成。
     *
     * 改版前這裡是逐格 `tween` `Sprite`／`Skeleton`／`Label` 的 color，還要為了倍率球的數字
     * 特地繞過去抓 `NgSymbol.coinLabel`——同一個顏色通道有好幾個主人，誰後到誰贏。
     *
     * 代價講清楚：舊版是 0.25 秒的漸暗補間，現在是瞬間切換（跟 1001／1003 一致）。要把淡入加回來，
     * 該加的地方是 `SymbolCell.applyColor()`，不是這裡。
     *
     * @param on true = 壓黑，false = 還原。
     */
    private setBlack(on: boolean): void {
        for (const reel of this.reelViews) {
            reel.setReelFlag(ReelFlag.Black, on);
        }
    }

    /**
     * 把不在中獎位置的符號壓暗，凸顯中獎組合。
     *
     * 中獎位置本身不需要在這裡處理——它們會被 `playSymbolWins` 設成 `WinAnimation`，優先權高於
     * 由旗標推算的 `Black`，自動不受壓黑影響。
     *
     * @param _winPositions 中獎格子的座標，保留參數維持呼叫端相容。
     */
    private dimNonWinning(_winPositions: { col: number; row: number }[]): void {
        this.setBlack(true);
    }

    updateStrips(iconMatrix: string[][]): void {
        for (let i = 0; i < this.reelViews.length; i++) {
            if (iconMatrix[i]) {
                this.reelViews[i].updateStrip(iconMatrix[i]);
            }
        }
    }
}
