export interface SpinStatusChangedEvent {
    eventId: typeof GAME_EVENT_ID.SPIN_STATUS_CHANGED;
    previousStatus: string;
    status: string;
}

export interface UserBalanceChangedEvent {
    eventId: typeof GAME_EVENT_ID.USER_BALANCE_CHANGED;
    balance: number;
}

export interface BetBalanceChangedEvent {
    eventId: typeof GAME_EVENT_ID.BET_BALANCE_CHANGED;
    betBalance: number;
}

export interface GameSpinDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_SPIN_DATA_CHANGED;
    spinData: SlotRoundResult | null;
}

export interface GameInitExtraChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_INIT_EXTRA_CHANGED;
    initExtra: unknown;
}

export interface GameConfigDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_CONFIG_DATA_CHANGED;
    configData: unknown;
}

export interface GameInitDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_INIT_DATA_CHANGED;
    gameInitData: unknown;
}

export interface DeviceOrientationChangedEvent {
    eventId: typeof GAME_EVENT_ID.DEVICE_ORIENTATION_CHANGED;
    orientation: '' | 'portrait' | 'landscape';
}

export interface BuyFeatureDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.BUY_FEATURE_DATA_CHANGED;
    data: { prefix: string; amount: string; mult: number } | null;
}

export interface BuyFeatureCloseChangedEvent {
    eventId: typeof GAME_EVENT_ID.BUY_FEATURE_CLOSE_CHANGED;
    requested: boolean;
}

export interface WinBalanceChangedEvent {
    eventId: typeof GAME_EVENT_ID.WIN_BALANCE_CHANGED;
    winBalance: number;
}

export interface ViewNameChangedEvent {
    eventId: typeof GAME_EVENT_ID.VIEW_NAME_CHANGED;
    viewName: any;
}

export interface GameViewNameChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_VIEW_NAME_CHANGED;
    gameViewName: any;
}

export interface DeleteViewNameChangedEvent {
    eventId: typeof GAME_EVENT_ID.DELETE_VIEW_NAME_CHANGED;
    deleteViewName: string;
}

export interface LoadingProgressChangedEvent {
    eventId: typeof GAME_EVENT_ID.LOADING_PROGRESS_CHANGED;
    progress: number;
}

export interface WinAnimationDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.WIN_ANIMATION_DATA_CHANGED;
    data: { totalWin: number; bet: number } | null;
}

export interface JackpotDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.JACKPOT_DATA_CHANGED;
    data: { jpType: string; amount: number } | null;
}

export interface TurboStatusChangedEvent {
    eventId: typeof GAME_EVENT_ID.TURBO_STATUS_CHANGED;
    turboStatus: string;
}

export interface AutoSpinStatusChangedEvent {
    eventId: typeof GAME_EVENT_ID.AUTO_SPIN_STATUS_CHANGED;
    autoSpinStatus: string;
}

export interface AutoSpinTimesChangedEvent {
    eventId: typeof GAME_EVENT_ID.AUTO_SPIN_TIMES_CHANGED;
    autoSpinTimes: any;
}

export interface IsLockChangedEvent {
    eventId: typeof GAME_EVENT_ID.IS_LOCK_CHANGED;
    isLock: boolean;
}

export interface CashierUrlChangedEvent {
    eventId: typeof GAME_EVENT_ID.CASHIER_URL_CHANGED;
    cashierURL: string;
}

export interface JackpotPoolDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.JACKPOT_POOL_DATA_CHANGED;
    jackpotPoolData: SlotApiJackpotPoolSnapshot;
}

export interface GroupTypeChangedEvent {
    eventId: typeof GAME_EVENT_ID.GROUP_TYPE_CHANGED;
    groupType: string;
}

export interface WinFreeGameDataChangedEvent {
    eventId: typeof GAME_EVENT_ID.WIN_FREE_GAME_DATA_CHANGED;
    data: { freeRoundCount: number } | null;
}

export interface FgRoundChangedEvent {
    eventId: typeof GAME_EVENT_ID.FG_ROUND_CHANGED;
    remaining: number;
    total: number;
    /** 這次變動是免費遊戲中再觸發加局加上來的局數 一般倒數為 0 */
    awarded?: number;
}

export interface GameModeChangedEvent {
    eventId: typeof GAME_EVENT_ID.GAME_MODE_CHANGED;
    gameMode: GameStateKey;
}

export interface ExtraBetChangedEvent {
    eventId: typeof GAME_EVENT_ID.EXTRA_BET_CHANGED;
    // 是否開放加注
    available: boolean;
    enabled: boolean;
}

/** 事件名稱與 payload 對照表 */
export interface GameRuntimeEvents {
    [GAME_EVENT_TYPE.SPIN_STATUS_CHANGED]: SpinStatusChangedEvent;
    [GAME_EVENT_TYPE.USER_BALANCE_CHANGED]: UserBalanceChangedEvent;
    [GAME_EVENT_TYPE.BET_BALANCE_CHANGED]: BetBalanceChangedEvent;
    [GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED]: GameSpinDataChangedEvent;
    [GAME_EVENT_TYPE.GAME_INIT_EXTRA_CHANGED]: GameInitExtraChangedEvent;
    [GAME_EVENT_TYPE.GAME_CONFIG_DATA_CHANGED]: GameConfigDataChangedEvent;
    [GAME_EVENT_TYPE.GAME_INIT_DATA_CHANGED]: GameInitDataChangedEvent;
    [GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED]: DeviceOrientationChangedEvent;
    [GAME_EVENT_TYPE.BUY_FEATURE_DATA_CHANGED]: BuyFeatureDataChangedEvent;
    [GAME_EVENT_TYPE.BUY_FEATURE_CLOSE_CHANGED]: BuyFeatureCloseChangedEvent;
    [GAME_EVENT_TYPE.WIN_BALANCE_CHANGED]: WinBalanceChangedEvent;
    [GAME_EVENT_TYPE.VIEW_NAME_CHANGED]: ViewNameChangedEvent;
    [GAME_EVENT_TYPE.GAME_VIEW_NAME_CHANGED]: GameViewNameChangedEvent;
    [GAME_EVENT_TYPE.DELETE_VIEW_NAME_CHANGED]: DeleteViewNameChangedEvent;
    [GAME_EVENT_TYPE.LOADING_PROGRESS_CHANGED]: LoadingProgressChangedEvent;
    [GAME_EVENT_TYPE.WIN_ANIMATION_DATA_CHANGED]: WinAnimationDataChangedEvent;
    [GAME_EVENT_TYPE.JACKPOT_DATA_CHANGED]: JackpotDataChangedEvent;
    [GAME_EVENT_TYPE.TURBO_STATUS_CHANGED]: TurboStatusChangedEvent;
    [GAME_EVENT_TYPE.AUTO_SPIN_STATUS_CHANGED]: AutoSpinStatusChangedEvent;
    [GAME_EVENT_TYPE.AUTO_SPIN_TIMES_CHANGED]: AutoSpinTimesChangedEvent;
    [GAME_EVENT_TYPE.IS_LOCK_CHANGED]: IsLockChangedEvent;
    [GAME_EVENT_TYPE.CASHIER_URL_CHANGED]: CashierUrlChangedEvent;
    [GAME_EVENT_TYPE.JACKPOT_POOL_DATA_CHANGED]: JackpotPoolDataChangedEvent;
    [GAME_EVENT_TYPE.GROUP_TYPE_CHANGED]: GroupTypeChangedEvent;
    [GAME_EVENT_TYPE.WIN_FREE_GAME_DATA_CHANGED]: WinFreeGameDataChangedEvent;
    [GAME_EVENT_TYPE.FG_ROUND_CHANGED]: FgRoundChangedEvent;
    [GAME_EVENT_TYPE.GAME_MODE_CHANGED]: GameModeChangedEvent;
    [GAME_EVENT_TYPE.EXTRA_BET_CHANGED]: ExtraBetChangedEvent;
}
